  failures: [
    { h: "Lab results did not survive the site.", t: "Zacua's partner, now on Origin's board, said at the raise that many construction robots look good in a lab and fail within a week on a live job. Buyers think the same, so proof has to come from working floors.", src: ["s5"] },
    { h: "Operated machines kept the labor problem.", t: "Canvas's machine needed a worker at the controls. A robot that one operator can supervise in multiples changes the crew math; one per machine does not.", src: ["s64", "s12"] },
    { h: "Small, chopped up jobs break the economics.", t: "Early finishing robots targeted continuous scopes over 10,000 sq ft. Qualify on wall area and layout before anything else.", src: ["s64"] },
    { h: "Money is flowing; adoption is the bottleneck.", t: "Construction robotics venture funding more than doubled in 2025, yet robots are under 0.03 percent of construction spend. The gap is trust and deployment, which is a go-to-market problem.", src: ["s6"] }
  ],

  /* ---------- I-200 ICP ---------- */
  icp: {
    statement: "US commercial wall and ceiling and painting subcontractors, $30M to $3B in revenue, that self-perform Level 4 and Level 5 finishing on large continuous interior scopes (data centers, multifamily, hotels, healthcare, offices) in markets where finisher hours are expensive or impossible to staff, with an operations leader who will sponsor a measured pilot.",
    firmo: [
      ["Segment", "Wall and ceiling contractors first; commercial painters second (priming)."],
      ["Size", "$30M to $3B revenue. Enough continuous wall area to keep robots busy."],
      ["Work", "Self-performed taping and finishing at Level 4 and Level 5."],
      ["Projects", "Continuous interior scopes of 10,000 sq ft or more: data halls, multifamily corridors and units, hotels, healthcare, offices."],
      ["Geography", "NYC metro first, then high wage metros, then Sun Belt volume markets."],
      ["Champion", "VP operations or general superintendent, with the finishing super on side."]
    ],
    tiers: [
      { id: "t1", name: "Tier 1, Northeast beachhead", def: "NYC metro and the Boston to Washington corridor. Inside the support radius of Origin's NYC team, with the highest finishing labor costs in the country.", play: "p1" },
      { id: "vet", name: "Robot veterans", def: "Contractors that already ran Canvas, Okibo or Dusty. They know the operating model and some are between programs.", play: "p3" },
      { id: "t2", name: "Tier 2, high wage markets", def: "West Coast, Midwest and Hawaii contractors where median taper wages run above the national median.", play: "p2" },
      { id: "t3", name: "Tier 3, Sun Belt volume", def: "Texas, Southeast, Arizona and Colorado. Lower wages, heavy data center and multifamily volume. Sell capacity and schedule.", play: "p4" },
      { id: "paint", name: "Painting contractors", def: "Large commercial painters with interior scopes. Lead with priming right behind finishing.", play: "p5" },
      { id: "nurture", name: "Nurture", def: "Committed to a competing finishing robot fleet. Stay visible; revisit at program review.", play: "p3" },
      { id: "excl", name: "Excluded", def: "Outside the US launch market or failing a disqualifier.", play: null }
    ],
    disq: [
      "Residential or small commercial contractors under about $10M revenue.",
      "Industrial coatings or exterior only painters.",
      "Portfolios of small, chopped up jobs with no continuous scope near 10,000 sq ft.",
      "Locked into an exclusive program with another finishing robot vendor.",
      "Outside the US for now, unless one of Origin's pilot countries."
    ],
    committee: [
      { r: "Owner or president", care: "Margin, risk, ability to bid more work with the same crew", fear: "Startup risk, crew backlash", win: "ROI model with their wages, pilot charter with exit criteria", titles: "President, CEO, Owner, Principal" },
      { r: "VP operations or general superintendent", tag: "Champion", care: "Hitting schedule with the crew they have", fear: "A robot that needs babysitting or sits idle", win: "Shift logs, operator ratio, a live site walk", titles: "VP Operations, Director of Operations, General Superintendent" },
      { r: "Finishing superintendent or taping foreman", tag: "Field veto", care: "Wall quality and crew acceptance", fear: "Punch lists and being blamed for the robot", win: "Let them judge walls on a live site and own the quality call", titles: "Finishing Superintendent, Taping Foreman, Drywall Foreman" },
      { r: "Innovation or VDC manager", care: "Technology roadmap and job data", fear: "A pilot that goes nowhere", win: "Data access, how the robot learns from operator corrections", titles: "Innovation Manager, VDC Manager, Director of Construction Technology" },
      { r: "Chief estimator", care: "Pricing robot work into bids", fear: "Wrong productivity assumptions", win: "Square feet per crew hour by finish level from real jobs", titles: "Chief Estimator, Preconstruction Manager" },
      { r: "Safety director", care: "Site traffic, dust, silica", fear: "An incident with a new machine", win: "Safety spec and operating procedure before the pilot", titles: "Safety Director, EHS Manager" },
      { r: "CFO or controller", care: "Cash and how the cost lands", fear: "Capital tied up in hardware", win: "Monthly cost against finisher hours saved", titles: "CFO, Controller" },
      { r: "Union business agent", care: "Member jobs, training, jurisdiction", fear: "Robots taking hours from members", win: "Operator roles for members and a training plan", titles: "Business Manager, Business Representative (tapers are typically IUPAT members)" },
      { r: "GC project executive or VP innovation", tag: "Influencer", care: "Schedule and sub performance", fear: "A sub's experiment on their job", win: "Pilot results shared with the GC", titles: "Project Executive, VP Innovation, Director of Preconstruction" }
    ]
  },

